// 1) Clientes recebidos do webhook (aceita lista direta ou { clientes: [...] })
const body = $('Webhook').first().json.body;
const clientes = Array.isArray(body) ? body : (body.clientes || [body]);

// 2) Parse do CSV de opcoes de investimento
const csv = $input.first().json.data;
const linhas = csv.trim().split(/\r?\n/).filter(l => l.trim());
const sep = linhas[0].includes(';') ? ';' : ',';
const cab = linhas[0].split(sep).map(h => h.trim().toLowerCase());
const opcoes = linhas.slice(1).map(l => {
  const c = l.split(sep);
  const o = {};
  cab.forEach((h, i) => o[h] = (c[i] || '').trim());
  return o;
});

const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const chavePerfil = cab.find(h => norm(h).includes('perfil')) || cab[0];

// 3) Templates estaticos por perfil (MVP)
const templates = {
  conservador: 'Seu perfil e Conservador, entao o foco e seguranca e renda fixa, preservando o seu patrimonio com previsibilidade.',
  moderado: 'Seu perfil e Moderado, entao sugerimos um mix equilibrado entre renda fixa e renda variavel, buscando crescimento com risco controlado.',
  arrojado: 'Seu perfil e Arrojado, entao a enfase esta em acoes e ativos de maior potencial de retorno, aceitando mais volatilidade.'
};

// 4) Cruza perfil x opcoes e gera a mensagem
return clientes.map(cli => {
  const perfil = norm(cli.perfil);
  const sugestoes = opcoes
    .filter(o => norm(o[chavePerfil]) === perfil)
    .map(o => '- ' + Object.entries(o).filter(([k]) => k !== chavePerfil).map(([k, v]) => k + ': ' + v).join(' | '));
  const intro = templates[perfil] || 'Preparamos algumas opcoes de investimento para voce.';
  const mensagem = 'Ola, ' + cli.nome + '!\n\n' + intro + '\n\nCom o saldo de ' + cli.saldo + ', estas sao as opcoes indicadas:\n' + (sugestoes.join('\n') || '- Sem opcoes cadastradas para este perfil.') + '\n\nFale com seu assessor para saber mais.';
  return { json: { nome: cli.nome, email: cli.email, saldo: cli.saldo, perfil: cli.perfil, mensagem } };
});
